package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(capacity, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		tokens:   capacity,
		last:     now,
		capacity: capacity,
		rate:     rate,
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	f := float64(n)
	if l.tokens >= f {
		l.tokens -= f
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		t := l.tokens + elapsed*l.rate
		if t > l.capacity {
			t = l.capacity
		}
		return t
	}
	return l.tokens
}
